200	// flushCheckpointRefsQueue drains the push-discovery queue and batch-pushes the
201	// recorded refs fast-forward-only, recovering a diverged ref by fetch+replay and
202	// removing from the queue only the refs that land. It returns the number pushed.
203	//
204	// Shared by the git-refs pre-push path (which logs and ignores the error to
205	// never block the user's push) and the migration command's opt-in push (which
206	// surfaces it). Stale entries — refs no longer present locally — are pruned so
207	// they don't block the queue forever.
208	func flushCheckpointRefsQueue(ctx context.Context, repo *git.Repository, pushTarget string) (int, error) {
209		queue, err := checkpoint.PushQueueForRepo(ctx, repo)
210		if err != nil {
211			return 0, fmt.Errorf("resolve push queue: %w", err)
212		}
213		queued, err := queue.Drain()
214		if err != nil {
215			return 0, fmt.Errorf("drain push queue: %w", err)
216		}
217		if len(queued) == 0 {
218			return 0, nil
219		}
220	
221		pushCtx, pushSpan := perf.Start(ctx, "push_checkpoint_refs")
222		defer pushSpan.End()
223	
224		existing, stale := partitionLocalRefs(repo, queued)
225		if len(stale) > 0 {
226			if err := queue.Remove(stale); err != nil {
227				logging.Warn(ctx, "git-refs push: prune stale queue entries failed",
228					slog.String("error", err.Error()))
229			}
230		}
231		if len(existing) == 0 {
232			return 0, nil
233		}
234	
235		// Progress: pushing many refs over the network can take tens of seconds, so
236		// surface it (matching the v1 path's "[entire] Pushing ..." line) instead of
237		// leaving the user's git push apparently hung. Written to stderr, which git
238		// shows during the pre-push hook.
239		displayTarget := displayPushTarget(pushTarget)
240		fmt.Fprintf(os.Stderr, "[entire] Pushing %d checkpoint ref(s) to %s...", len(existing), displayTarget)
241		stop := startProgressDots(os.Stderr)
242	
243		// Fast path: push all refs in one round-trip (fast-forward-only). If every
244		// ref was up to date or fast-forwarded, we're done.
245		if err := batchPushRefs(pushCtx, pushTarget, existing); err == nil {
246			stop(" done")
247			if removeErr := queue.Remove(existing); removeErr != nil {
248				logging.Warn(ctx, "git-refs push: clear pushed refs from queue failed",
249					slog.String("error", removeErr.Error()))
250			}
251			return len(existing), nil
252		}
253		stop("")
254	
255		// At least one ref was rejected — typically a non-fast-forward divergence
256		// (the same checkpoint re-written on another machine). Retry per ref with
257		// fetch+replay recovery, and remove from the queue only the refs that land
258		// (a genuine cherry-pick conflict leaves that ref queued for a later push,
259		// never force-overwriting the remote).
260		fmt.Fprintf(os.Stderr, "[entire] Some checkpoint refs diverged; syncing %d ref(s) individually...", len(existing))
261		stop = startProgressDots(os.Stderr)
262		pushed := make([]plumbing.ReferenceName, 0, len(existing))
263		var firstErr error
264		for _, ref := range existing {
265			if err := pushCheckpointRefWithRecovery(pushCtx, pushTarget, ref); err != nil {
266				logging.Warn(ctx, "git-refs push: checkpoint ref push/sync failed; left queued, not overwritten",
267					slog.String("ref", ref.String()), slog.String("error", err.Error()))
268				if firstErr == nil {
269					firstErr = err
270				}
271				continue
272			}
273			pushed = append(pushed, ref)
274		}
275		stop(fmt.Sprintf(" pushed %d of %d", len(pushed), len(existing)))
276		if err := queue.Remove(pushed); err != nil {
277			logging.Warn(ctx, "git-refs push: clear pushed refs from queue failed",
278				slog.String("error", err.Error()))
279		}
280		if firstErr != nil {
281			return len(pushed), fmt.Errorf("%d of %d checkpoint refs failed to push: %w",
282				len(existing)-len(pushed), len(existing), firstErr)
283		}
284		return len(pushed), nil
285	}
