15	// handleList implements the git-remote-helpers "list" / "list for-push"
16	// command. It fetches the v0 info/refs advertisement, extracts each
17	// ref and HEAD's symref target from the embedded capabilities, and
18	// writes one "<value> <name>" line per ref followed by a blank-line
19	// terminator. HEAD is emitted as "@<target> HEAD" when the symref
20	// capability resolves; detached HEAD falls back to "<sha> HEAD".
21	func handleList(ctx context.Context, t Transport, forPush bool, stdout io.Writer) error {
22		service := serviceUploadPack
23		if forPush {
24			service = serviceReceivePack
25		}
26		refs, err := t.InfoRefs(ctx, service)
27		if err != nil {
28			return fmt.Errorf("list %s info/refs: %w", service, err)
29		}
30		defer refs.Close()
31	
32		r := bufio.NewReader(refs)
33		var reply packp.SmartReply
34		if err := reply.Decode(r); err != nil {
35			return fmt.Errorf("parsing info/refs: %w", err)
36		}
37	
38		type entry struct{ value, name string }
39		var (
40			lines        []entry
41			headValue    string
42			objectFormat string
43			symrefs      = map[string]string{}
44			first        = true
45		)
46		for {
47			_, content, err := pktline.ReadLine(r)
48			if err != nil {
49				if errors.Is(err, io.EOF) {
50					break
51				}
52				return fmt.Errorf("reading ref pkt-line: %w", err)
53			}
54			if len(content) == 0 {
55				// Flush, delim, or response-end. For the v0 ref
56				// advertisement only flush is meaningful — it ends
57				// the list.
58				break
59			}
60			line := strings.TrimRight(string(content), "\n")
61	
62			// The first advertised ref carries the capability list after a
63			// NUL separator: "<sha> <ref>\0<cap1> <cap2> ...". Subsequent
64			// refs are bare. We pluck every symref=src:dst pair and
65			// object-format=<hash> out of those caps; the rest is for the
66			// smart-transport client only.
